518	/// The state for the deterministic scheduler.
519	#[derive(Debug)]
520	pub struct Scheduler {
521	    /// Monotonically count upwards.
522	    pub turn: u64,
523	
524	    /// The queue of logically UNBLOCKED guest threads waiting for a turn.  After a new
525	    /// thread is created, it should always have an entry in here, but it goes to the end
526	    /// of the line after its turn. Unblocked threads are dequed in priority order, then
527	    /// round-robin within a priority level.
528	    /// NB: Polling threads are considered unblocked, and their polling intervals are managed by the RunQueue
529	    pub run_queue: RunQueue,
530	
531	    /// Stores the communication endpoints for rendevous with each guest on its next turn.
532	    /// When the thread parks it provides its request for resources, and waits for a
533	    /// response.  After a new thread is created, it should always have an entry in here.
534	    ///
