1248	/// Not an error, but simply a turn that cannot do productive work.
1249	#[derive(Debug, Clone)]
1250	pub struct SkipTurn;
1251	
1252	/// Scheduler-local attribution also represents process operations that have no
1253	/// selected task. The public backend callback still supplies its actual task.
1254	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
1255	struct BackendFailureLocation {
1256	    pid: reverie::Pid,
