3722	                // supervisor has not received its final wait status. Fast-forwarding the next
3723	                // timer here can fire a parent's timeout before the child becomes waitable.
3724	                trace!(
3725	                    "waiting for physical process exits before empty-queue timer fast-forward: {:?}",
3726	                    self.pending_physical_process_exits
3727	                );
3728	                std::thread::yield_now();
3729	                return Err(SkipTurn);
3730	            }
