4284	    /// Helper for priority changepoint logic
4285	    ///
4286	    /// Precondition: guest is stopped so that there is no chance the ivars are being used
4287	    /// concurrently while they are being cleared.
4288	    ///
4289	    /// Postcondition: Same as block_for_one_resource. However, always returns SkipTurn, because the
4290	    /// priority changepoint may not allow the current thread to continue in a regular turn (i.e.
4291	    /// doing actual work).
4292	    fn perform_priority_changepoint(
4293	        &mut self,
4294	        dettid: DetTid,
4295	
4296	        new_priority: Priority,
4297	        guest_time: LogicalTime,
4298	        guest_rcbs: u64,
4299	        // AUTONOMOUS-BOT-IMPLEMENTED
4300	        // TODO-HUMAN-REVIEW(PR-1151)
4301	        chaos_epochs: &[crate::resources::ChaosEpochTransition],
4302	    ) -> Result<(), SkipTurn> {
4303	        assert!(runqueue::is_ordinary_priority(new_priority));
4304	        // Alter the threads priority and requeue.
4305	        let old_priority = self.priorities.insert(dettid, new_priority);
4306	
4307	        // Do not attempt to record preemptions/priorities when we're dictated by a raw schedule replay.
4308	        if self.replayer.is_none()
4309	            && let Some(pw) = &mut self.preemption_writer
4310	        {
4311	            let old_prio = old_priority.unwrap();
4312	            debug!(
4313	                "[dtid {}] Recording preemption point, current time {} prior priority {} (next priority {})",
4314	                dettid, guest_time, old_prio, new_priority
4315	            );
4316	            for transition in chaos_epochs {
4317	                pw.insert_chaos_epoch(dettid, *transition);
4318	            }
4319	            pw.insert_reprioritization(dettid, guest_time, guest_rcbs, old_prio, new_priority);
