4647	    /// Step: reenqueue the thread that just had a turn.
4648	    fn step6_reenquue(&mut self, next_dtid: DetTid, sched_yield: bool) {
4649	        // We delay popping till here, so while holding the lock we "atomically" move the
4650	        // thread from the front to the back of the queue.
