4669	    fn step7_simulate_exit_posthook(
4670	        &mut self,
4671	        dettid: DetTid,
4672	        placeholder_syscall: Syscall,
4673	        global_time: &Mutex<GlobalTime>,
4674	    ) {
4675	        let replay = self.replayer.is_some();
4676	        let record = self.preemption_writer.is_some();
4677	        if !(replay || record) {
4678	            return;
4679	        }
4680	        let thread_duration = global_time.lock().unwrap().threads_duration(dettid);
4681	        debug!(
4682	            "simulate exit posthook on tid {}, thread time {}: {:?}",
4683	            dettid, thread_duration, placeholder_syscall
4684	        );
4685	
4686	        let ev = SchedEvent::syscall(dettid, placeholder_syscall.number(), SyscallPhase::Posthook)
4687	            .with_time(thread_duration);
4688	        let print_stack1 = if replay {
4689	            let ConsumeResult {
4690	                keep_running,
4691	                print_stack,
4692	                event_ix: _,
4693	                timeslice_remaining: _,
4694	            } = self.consume_schedevent(&ev);
4695	            // We should not ever need to background the thread when it is going to exit anyway.
4696	            if !keep_running {
4697	                tracing::warn!(
4698	                    "simulate_exit_posthook: unexpectedly asked to background the current, exiting thread {}",
4699	                    dettid
4700	                );
4701	            }
4702	            print_stack
4703	        } else {
4704	            None
4705	        };
4706	        let print_stack2 = if record { self.record_event(&ev) } else { None };
4707	        if print_stack1.is_some() || print_stack2.is_some() {
4708	            eprintln!(
4709	                ":: Guest tid {}, at thread time {}, backtrace requested but not available post-exit!\n",
4710	                dettid, thread_duration
4711	            );
4712	        }
4713	    }
