4969	    /// Drain removals deferred by [`Scheduler::deschedule_or_defer`] at the same
4970	    /// deterministic `step2` point as admissions, and *before* them, so a thread
4971	    /// killed while an admission was still buffered is not re-enqueued. The
4972	    /// window is closed here (`tentative_selection` is `None`), so
4973	    /// `remove_tid`'s guard holds. The `BTreeMap` makes removal order canonical;
4974	    /// each disposition determines whether a same-raw-TID admission is stale or
4975	    /// is the explicitly paired exec replacement.
4976	    fn drain_pending_run_queue_removals(&mut self) {
4977	        if self.pending_run_queue_removals.is_empty() {
4978	            return;
4979	        }
4980	        let pending = std::mem::take(&mut self.pending_run_queue_removals);
4981	        for (dtid, disposition) in pending {
4982	            match disposition {
4983	                RemovalDisposition::Retire => {
4984	                    // Ordinary logical death cancels a buffered admission for
4985	                    // the same thread incarnation.
4986	                    self.pending_run_queue_admissions.remove(&dtid);
4987	                }
4988	                RemovalDisposition::ReplaceThenAdmit => {
4989	                    assert!(
4990	                        self.next_turns.contains_key(&dtid),
4991	                        "exec replacement {:?} lost its scheduler registration",
4992	                        dtid
4993	                    );
4994	                    assert!(
4995	                        self.pending_run_queue_admissions.contains_key(&dtid),
4996	                        "exec replacement {:?} lost its paired admission",
4997	                        dtid
4998	                    );
4999	                    assert!(
5000	                        !self.thread_is_logically_killed(dtid),
5001	                        "logically dead exec replacement {:?} reached the drain",
5002	                        dtid
5003	                    );
5004	                }
5005	            }
5006	            // Always remove the old physical queue slot before a replacement
5007	            // admission is applied. This prevents the new image from inheriting
5008	            // the destroyed leader's round-robin position.
5009	            let _ = self.run_queue.remove_tid(dtid);
