5146	    /// Build the full report and the INFO preemption description together.
5147	    /// The latter retains counts/history but excludes the host output filename.
5148	    /// This performs one generation and flush.
5149	    pub(crate) fn generate_partial_run_summary_for_log(
5150	        &mut self,
5151	        preemptions_to: Option<&PathBuf>,
5152	    ) -> anyhow::Result<(RunSummary, Option<String>)> {
5153	        let schedevent_replayed = self
5154	            .replayer
5155	            .as_ref()
5156	            .map(|r| r.events_popped)
5157	            .unwrap_or_default();
5158	        let total_desync_stats = self
5159	            .replayer
5160	            .as_ref()
5161	            .map(|r| {
5162	                r.desync_counts
5163	                    .values()
5164	                    .fold(Default::default(), |x: DesyncStats, y: &DesyncStats| x + *y)
5165	            })
5166	            .unwrap_or_default();
5167	
5168	        let total_desyncs = total_desync_stats.soft + total_desync_stats.hard;
5169	        let desync_descrip = if total_desyncs > 0 {
5170	            let mut buf = String::new();
5171	            write!(
5172	                buf,
5173	                "  Encountered {} soft desyncs, {} hard (with {} at context switch points), {} resyncs ({}/{} insertion/deletion).\n  Per thread (soft,hard,@switch,resync): ",
5174	                total_desync_stats.soft,
5175	                total_desync_stats.hard,
5176	                total_desync_stats.at_context_switch,
5177	                total_desync_stats.resync_insertions + total_desync_stats.resync_deletions,
5178	                total_desync_stats.resync_insertions,
5179	                total_desync_stats.resync_deletions,
5180	            )?;
5181	            if let Some(ref replayer) = self.replayer {
5182	                for (tid, desync_stats) in replayer.desync_counts.iter() {
5183	                    write!(
5184	                        buf,
5185	                        "{}=>({},{},{},{}) ",
5186	                        tid,
5187	                        desync_stats.soft,
5188	                        desync_stats.hard,
5189	                        desync_stats.at_context_switch,
5190	                        desync_stats.resync_insertions + desync_stats.resync_deletions,
5191	                    )?;
5192	                }
5193	            }
5194	            writeln!(buf)?;
5195	            Some(buf)
5196	        } else {
5197	            None
5198	        };
5199	
5200	        let (reprio_descrip, info_reprio_descrip) = if let Some(pw) = self.preemption_writer.take()
5201	        {
5202	            let mut buf = String::new();
5203	            writeln!(
5204	                buf,
5205	                "Record of {} preemption and reprioritization events:",
5206	                pw.len()
5207	            )?;
5208	            let info_description;
5209	            if let Some(path) = preemptions_to {
5210	                // Preserve the full human/JSON description; build the INFO
5211	                // description before adding the host artifact destination.
5212	                info_description = buf.clone();
5213	                writeln!(buf, "  (Writing to file {:?})", path)?;
5214	                if let Err(str) = pw.flush() {
5215	                    tracing::warn!("{}", str);
5216	                }
5217	            } else {
5218	                // Recording, but not outputting to file, so this is the only (partial) record of it:
5219	                writeln!(buf, "{}", truncated(200, pw.into_string()))?;
5220	                info_description = buf.clone();
5221	            }
5222	            (Some(buf), Some(info_description))
5223	        } else {
5224	            (None, None)
5225	        };
5226	
5227	        let num_processes = self.thread_tree.thread_group_leaders.len() as u64;
5228	        let num_threads = self.thread_tree.size() as u64;
5229	        let threads_descrip = format!("{}", self.thread_tree);
5230	
5231	        // Aggregate the per-thread timeslice distributions collected at thread
5232	        // exit. BTreeMap gives a deterministic (dettid-sorted) ordering.
5233	        let per_thread_timeslice: Vec<(DetTid, TimesliceStats)> = self
5234	            .per_thread_timeslice
5235	            .iter()
5236	            .map(|(k, v)| (*k, *v))
5237	            .collect();
5238	        let mut timeslice_stats = TimesliceStats::default();
5239	        for (_, st) in &per_thread_timeslice {
5240	            timeslice_stats.merge(st);
5241	        }
5242	        let syscalls = self.per_thread_syscalls.values().copied().sum();
5243	
5244	        Ok((
5245	            RunSummary {
5246	                sched_turns: self.turn,
5247	                schedevent_replayed,
5248	                schedevent_recorded: self.recorded_event_count,
5249	                schedevent_desynced: total_desyncs,
5250	                // schedevent_desynced_at_context_switch: total_desyncs.at_context_switch,
5251	                desync_descrip,
5252	                reprio_descrip,
5253	                threads_descrip,
5254	                num_processes,
5255	                num_threads,
5256	                syscalls: Some(syscalls),
5257	                virttime_elapsed: 0, // Cannot fill.
5258	                virttime_final: 0,   // Cannot fill.
5259	                realtime_elapsed: None,
5260	                timeslice_stats,
5261	                per_thread_timeslice,
5262	            },
5263	            info_reprio_descrip,
5264	        ))
5265	    }
