5268	    pub fn full_summary(&self) -> String {
5269	        let mut buf = String::new();
5270	        write!(&mut buf, "  {}", self.run_queue).unwrap();
5271	
5272	        let total_futex_blocked: usize = self.blocked.futex_waiters.iter().map(|v| v.1.len()).sum();
5273	        writeln!(
5274	            &mut buf,
5275	            "\n  Futex-waiters, {} blocked on {} futexes:",
5276	            total_futex_blocked,
5277	            self.blocked.futex_waiters.len()
5278	        )
5279	        .unwrap();
5280	        // Sorted, and no `Ivar` Debug. `format_terminal_deadlock` above already
5281	        // documents the two sources this avoids, and this function had neither
5282	        // guard: `futex_waiters` is a `HashMap`, so it iterates in a randomized
5283	        // order once it holds more than one entry, and `FutexWaiter`'s derived
5284	        // `Debug` prints its `Ivar`'s parked waker as raw host pointers.
5285	        //
5286	        // Measured before this change, three runs of
5287	        // `--stop-after-turn=15 -- rustbin_futex_and_print`, which reaches this
5288	        // function through the `--stop-after-turn` warning:
5289	        //   Waker { data: 0x564ea2a82c80
5290	        //   Waker { data: 0x55f2120b9c80
5291	        //   Waker { data: 0x56163deeec80
5292	        // Three runs, three host addresses, in a WARN record that
5293	        // `--verify-strict` compares.
5294	        //
5295	        // Only guest-level identities are printed here: the futex key, the
5296	        // waiting dettid and the bitset are all values Detcore already
5297	        // determinizes.
5298	        let mut futex_rows: Vec<String> = self
5299	            .blocked
5300	            .futex_waiters
5301	            .iter()
5302	            .map(|(futex, waiters)| {
5303	                let mut dettids: Vec<String> =
5304	                    waiters.iter().map(|w| w.dettid.to_string()).collect();
5305	                dettids.sort();
5306	                let mut bitsets: Vec<u32> = waiters.iter().map(|w| w.bitset).collect();
5307	                bitsets.sort_unstable();
5308	                format!(
5309	                    "    {:?} => {} waiter(s), dettids [{}], bitsets {:?}",
5310	                    futex,
5311	                    waiters.len(),
5312	                    dettids.join(", "),
5313	                    bitsets
5314	                )
5315	            })
5316	            .collect();
5317	        futex_rows.sort();
5318	        for row in futex_rows {
5319	            writeln!(&mut buf, "{}", row).unwrap();
5320	        }
5321	
5322	        writeln!(
5323	            &mut buf,
5324	            "\n  Timed-waiters, {}:",
5325	            self.blocked.timed_waiters.len()
5326	        )
5327	        .unwrap();
5328	        for (time, dtid) in self.blocked.timed_waiters.iter() {
5329	            writeln!(&mut buf, "    {} => {}", time, dtid).unwrap();
5330	        }
5331	
5332	        writeln!(
5333	            &mut buf,
5334	            "\n  External-IO-blocked, {}:",
5335	            self.blocked.external_io_blockers.len(),
5336	        )
5337	        .unwrap();
5338	        for x in &self.blocked.external_io_blockers {
5339	            writeln!(&mut buf, "    {:?}", x).unwrap();
5340	        }
5341	
5342	        writeln!(
5343	            &mut buf,
5344	            "\n  Rt-sigsuspend-blocked, {}:",
