+        {
+            ProcessFamilyExit::Child(snapshot) => snapshot.pending_generation,
+            other => panic!("unexpected child family exit: {other:?}"),
+        };
+        install(
+            &mut parent,
+            KernelSigaction {
+                handler: libc::SIG_IGN as u64,
+                ..Default::default()
