+        assert_eq!(receipt.pending_generation, exit_generation);
+        assert_eq!(
+            receipt.effect,
+            reverie::ChildExitPublicationEffect::DiscardedByDispositionChange
+        );
+        assert!(
+            !parent
+                .state
+                .process_signals
+                .lock()
+                .unwrap()
+                .shared_pending
